export { sfSymbolExports } from "#src/icons/apple-symbol-exports.js";

/**
 * The real SF Symbols, as exported from the SF Symbols app.
 */

/*
 * This is the canonical set for the workspace.
 */

/*
 * A project that shows a Mac app shows the Mac's own symbols, so an export lands here once and every project that draws the same product gets it.
 */

/*
 * Adding one is a paste: export from the SF Symbols app at Regular weight and Medium scale, drop the transparent background rect and the `fill-opacity` it stamps on every path,
 */

/*
 * and keep the rest verbatim so the entry can be replaced by a fresh export later.
 */

/*
 * The exports are tight bounding boxes in a shared unit space, which is what lets one canvas hold all of them: a symbol keeps its size relative to the others
 */

/*
 * instead of being stretched to fill a square.
 */

/*
 * `CANVAS` is that square, and 768 is where a 16px render puts trash at 12.5px and doc.on.doc at 13.1px, the sizes the drawings they replaced had been tuned to by
 */

/*
 * eye.
 */

/*
 * A name that is not here yet still falls back to the drawing in `Icon.svelte`.
 */

// =========================
// TYPES
// =========================
export interface SFSymbol {
  /** The export's own viewBox width. */
  w: number;
  /** The export's own viewBox height. */
  h: number;
  /** Each `d` from the export, in order. */
  paths: string[];
}

// =========================
// CONSTANTS
// =========================
export const CANVAS = 768;

